-- Peelr August 2026 questions: LOVERS
-- Theme: End of Summer, before it's over. Flirty, a little urgent, the 2am questions.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
-- Layer 1: playful, flirty, light
('lovers', 1, 'What is the one summer night with me you would live again exactly as it happened?', '¿Cuál es la noche de verano conmigo que volverías a vivir exactamente igual?'),
('lovers', 1, 'If we had one more perfect summer day together, what are we doing from morning to midnight?', 'Si tuviéramos un día perfecto más de verano juntos, ¿qué hacemos desde la mañana hasta la medianoche?'),
('lovers', 1, 'When did I look best to you this summer?', '¿Cuándo te gusté más este verano?'),
('lovers', 1, 'What is your favorite photo of us from this summer and why that one?', '¿Cuál es tu foto favorita de nosotros este verano y por qué esa?'),
('lovers', 1, 'If summer ended tomorrow, what is the first thing you would want to do with me tonight?', 'Si el verano terminara mañana, ¿qué es lo primero que querrías hacer conmigo esta noche?'),
('lovers', 1, 'What song from this summer is going to sound like me for the rest of your life?', '¿Qué canción de este verano va a sonar como yo por el resto de tu vida?'),
('lovers', 1, 'Where did you want to kiss me this summer and did not?', '¿Dónde quisiste besarme este verano y no lo hiciste?'),
('lovers', 1, 'What is something small I did this summer that you have not stopped thinking about?', '¿Qué cosa pequeña hice este verano en la que no has dejado de pensar?'),
('lovers', 1, 'If we could disappear for one last weekend before fall, where are we going?', 'Si pudiéramos desaparecer un último fin de semana antes del otoño, ¿a dónde vamos?'),
('lovers', 1, 'What is your favorite thing about how I look right now, tonight?', '¿Qué es lo que más te gusta de cómo me veo ahora mismo, esta noche?'),
('lovers', 1, 'What summer plan did we never get around to that you still want?', '¿Qué plan de verano nunca cumplimos que todavía quieres?'),
('lovers', 1, 'If you had to describe our summer in one word, what is it?', 'Si tuvieras que describir nuestro verano en una palabra, ¿cuál es?'),
('lovers', 1, 'What is something you want to try with me before the weather turns?', '¿Qué quieres probar conmigo antes de que cambie el clima?'),
('lovers', 1, 'What was the best kiss of this summer and where were we?', '¿Cuál fue el mejor beso de este verano y dónde estábamos?'),
('lovers', 1, 'What is something I wear that you hope I keep wearing into fall?', '¿Qué me pongo que esperas que siga usando en el otoño?'),
('lovers', 1, 'If tonight was the last warm night of the year, how are we spending it?', 'Si esta fuera la última noche cálida del año, ¿cómo la pasamos?'),
('lovers', 1, 'What is the flirtiest thing you wanted to text me this summer but never sent?', '¿Cuál es el mensaje más coqueto que quisiste enviarme este verano y nunca mandaste?'),
('lovers', 1, 'What made you look at me this summer like it was the first time again?', '¿Qué hizo que me miraras este verano como si fuera la primera vez otra vez?'),
('lovers', 1, 'What is one summer memory of us you would put on a loop?', '¿Qué recuerdo nuestro de este verano pondrías en repetición?'),
('lovers', 1, 'What do you want more of from me before summer is over?', '¿Qué quieres más de mí antes de que termine el verano?'),
-- Layer 2: personal, warm, getting real
('lovers', 2, 'What did this summer show you about us that you did not know in June?', '¿Qué te mostró este verano sobre nosotros que no sabías en junio?'),
('lovers', 2, 'What is something you needed from me this summer that you never asked for?', '¿Qué necesitaste de mí este verano que nunca pediste?'),
('lovers', 2, 'When did you feel closest to me these past few months?', '¿Cuándo te sentiste más cerca de mí estos últimos meses?'),
('lovers', 2, 'What is a way I changed this summer that you noticed before I did?', '¿En qué cambié este verano que notaste antes que yo?'),
('lovers', 2, 'What about our life together do you not want to lose when things get busy again?', '¿Qué de nuestra vida juntos no quieres perder cuando todo se ponga ocupado otra vez?'),
('lovers', 2, 'What did you enjoy about me this summer that surprised you?', '¿Qué disfrutaste de mí este verano que te sorprendió?'),
('lovers', 2, 'What is a moment this summer you wish had lasted longer?', '¿Qué momento de este verano deseas que hubiera durado más?'),
('lovers', 2, 'What are you hoping we carry into fall from these months?', '¿Qué esperas que llevemos al otoño de estos meses?'),
